/// The host node "rtcVideo": its registration, and the glue between the holder and the instance.
public enum UIRTCVideoNodeGlue {
    /// What the halves register under: the node's kind.
    public static let name = "rtcVideo"
    /// The contract's version: the highest `@since` of its members.
    public static let version = 1

    /// Register the node: `make` builds one instance per node of the kind, when the SDK creates one.
    public static func register(in engine: LeCodesEngine, _ make: @escaping (UIRTCVideoNodeEvents) -> UIRTCVideoNodeInstance) {
        engine.registerNode(name, version: Int32(version)) { channel in
            make(UIRTCVideoNodeEvents(channel: channel))
        }
    }

    /// A prop the SDK wrote: its text, nil when it was cleared.
    static func setProperty(_ i: UIRTCVideoNodeInstance, _ name: String, _ value: String?) {
        switch name {
        case "trackId":
            i.set(trackId: value)
        case "objectFit":
            guard let value else { return i.set(objectFit: nil) }
            guard let v = ObjectFit(rawValue: value) else { return dropped(name) }
            i.set(objectFit: v)
        case "mirror":
            guard let value else { return i.set(mirror: nil) }
            guard let v = bool(value) else { return dropped(name) }
            i.set(mirror: v)
        default:
            break   // `kind` (the holder's), or a prop of a newer contract
        }
    }

    /// A call of the SDK: read off the wire and handed to the instance; a malformed call never reaches it.
    static func call(_ i: UIRTCVideoNodeInstance, _ method: String, wire args: WireIn, _ settle: ChannelSettle) {
        switch method {
        case "setTrack":
            let w0 = args[0]
            var a0: String? = nil
            if w0.isPresent {
                guard let v = w0.string else { return settle.reject("bad arguments — UIRTCVideo.setTrack: trackId") }
                a0 = v
            }
            i.setTrack(a0, Reply<Void, UIRTCVideoNodeCode>(settle))
        case "setObjectFit":
            guard let a0 = ObjectFit(wire: args[0]) else { return settle.reject("bad arguments — UIRTCVideo.setObjectFit: fit") }
            i.setObjectFit(a0, Reply<Void, UIRTCVideoNodeCode>(settle))
        case "setMirror":
            guard let a0 = args[0].bool else { return settle.reject("bad arguments — UIRTCVideo.setMirror: mirror") }
            i.setMirror(a0, Reply<Void, UIRTCVideoNodeCode>(settle))
        default:
            settle.reject("Unknown method: \(method)")
        }
    }

    private static func bool(_ text: String) -> Bool? { text == "1" ? true : text == "0" ? false : nil }

    private static func dropped(_ prop: String) {
        print("LeCodes: the node \"\(Self.name)\" dropped a value of \(prop) its contract does not read")
    }
}
